-- All test changes are rolled back. Uses existing identities, never duplicates accounts.
BEGIN;
CREATE TEMP TABLE access_results(scenario int,status text,evidence jsonb);
GRANT SELECT,INSERT,UPDATE ON access_results TO authenticated;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','55b423f1-4d0c-43d4-aac1-71ba8538e6af',true);
INSERT INTO access_results SELECT 1,CASE WHEN count(*)=2 THEN 'PASSOU' ELSE 'FALHOU' END,jsonb_build_object('companies',count(*)) FROM public.empresas;
INSERT INTO access_results SELECT 2,CASE WHEN count(*)=2 THEN 'PASSOU' ELSE 'FALHOU' END,'{}' FROM public.empresas WHERE id IN ('bf381a72-3d4e-4ce9-920a-e4c2409bfdb8','e7e31086-e542-4a76-9cd1-52a909a6cc02');
SELECT set_config('request.jwt.claim.sub','da814b09-4d0f-4263-b198-3652e2fe4097',true);
DO $$ DECLARE aid uuid; BEGIN aid:=public.iniciar_atendimento('bf381a72-3d4e-4ce9-920a-e4c2409bfdb8','Teste integrado de isolamento'); INSERT INTO access_results VALUES(3,CASE WHEN EXISTS(SELECT 1 FROM public.suporte_atendimentos WHERE id=aid AND usuario_id=auth.uid()) THEN 'PASSOU' ELSE 'FALHOU' END,'{}'); PERFORM public.encerrar_atendimento(aid); END $$;
DO $$ BEGIN BEGIN INSERT INTO public.plataforma_usuarios(user_id,papel) VALUES(auth.uid(),'admin_master'); INSERT INTO access_results VALUES(4,'FALHOU','{}'); EXCEPTION WHEN OTHERS THEN INSERT INTO access_results VALUES(4,'PASSOU',jsonb_build_object('denied',SQLSTATE)); END; END $$;
INSERT INTO access_results SELECT 5,CASE WHEN NOT public.tem_capacidade(auth.uid(),'financeiro.gerenciar') AND public.empresa_atual() IS NULL AND NOT EXISTS(SELECT 1 FROM public.pagamentos) THEN 'PASSOU' ELSE 'FALHOU' END,'{}';
SELECT set_config('request.jwt.claim.sub','15ba9344-a725-48b8-a9f1-53de3a662af0',true);
INSERT INTO access_results SELECT 6,CASE WHEN count(*)=1 AND bool_and(id='bf381a72-3d4e-4ce9-920a-e4c2409bfdb8') THEN 'PASSOU' ELSE 'FALHOU' END,'{}' FROM public.empresas;
DO $$ DECLARE n int; BEGIN UPDATE public.empresas SET nome=nome WHERE id='e7e31086-e542-4a76-9cd1-52a909a6cc02'; GET DIAGNOSTICS n=ROW_COUNT; INSERT INTO access_results VALUES(7,CASE WHEN n=0 AND NOT EXISTS(SELECT 1 FROM public.eventos WHERE empresa_id='e7e31086-e542-4a76-9cd1-52a909a6cc02') THEN 'PASSOU' ELSE 'FALHOU' END,jsonb_build_object('changed',n)); END $$;
INSERT INTO access_results SELECT 11,CASE WHEN NOT EXISTS(SELECT 1 FROM public.cobrancas WHERE empresa_id<>'bf381a72-3d4e-4ce9-920a-e4c2409bfdb8') AND NOT EXISTS(SELECT 1 FROM public.movimentos_saldo WHERE empresa_id<>'bf381a72-3d4e-4ce9-920a-e4c2409bfdb8') AND NOT EXISTS(SELECT 1 FROM public.fundings WHERE empresa_id<>'bf381a72-3d4e-4ce9-920a-e4c2409bfdb8') THEN 'PASSOU' ELSE 'FALHOU' END,'{}';
INSERT INTO access_results SELECT 12,CASE WHEN NOT EXISTS(SELECT 1 FROM public.eventos WHERE empresa_id<>'bf381a72-3d4e-4ce9-920a-e4c2409bfdb8') AND NOT EXISTS(SELECT 1 FROM public.freelancers WHERE empresa_id<>'bf381a72-3d4e-4ce9-920a-e4c2409bfdb8') THEN 'PASSOU' ELSE 'FALHOU' END,'{}';
INSERT INTO access_results SELECT 13,CASE WHEN NOT EXISTS(SELECT 1 FROM public.pontos p JOIN public.escalas s ON s.id=p.escala_id JOIN public.equipes e ON e.id=s.equipe_id JOIN public.eventos v ON v.id=e.evento_id WHERE v.empresa_id<>'bf381a72-3d4e-4ce9-920a-e4c2409bfdb8') AND NOT EXISTS(SELECT 1 FROM public.pagamentos p JOIN public.fechamentos f ON f.id=p.fechamento_id JOIN public.escalas s ON s.id=f.escala_id JOIN public.equipes e ON e.id=s.equipe_id JOIN public.eventos v ON v.id=e.evento_id WHERE v.empresa_id<>'bf381a72-3d4e-4ce9-920a-e4c2409bfdb8') THEN 'PASSOU' ELSE 'FALHOU' END,'{}';
INSERT INTO access_results SELECT 14,CASE WHEN (SELECT coalesce(sum(case when tipo = 'credito' then valor else -valor end), 0) FROM public.movimentos_saldo) = 1.94 AND NOT EXISTS (SELECT 1 FROM public.movimentos_saldo WHERE empresa_id <> 'bf381a72-3d4e-4ce9-920a-e4c2409bfdb8') AND (SELECT public.saldo_empresa('bf381a72-3d4e-4ce9-920a-e4c2409bfdb8')) = 1.94 AND (SELECT public.saldo_empresa('e7e31086-e542-4a76-9cd1-52a909a6cc02')) = 0 THEN 'PASSOU' ELSE 'FALHOU' END,jsonb_build_object('saldo',(SELECT coalesce(sum(case when tipo = 'credito' then valor else -valor end), 0) FROM public.movimentos_saldo));
DO $$ BEGIN BEGIN UPDATE public.usuarios SET empresa_id='e7e31086-e542-4a76-9cd1-52a909a6cc02' WHERE id=auth.uid(); INSERT INTO access_results VALUES(15,'FALHOU','{}'); EXCEPTION WHEN OTHERS THEN INSERT INTO access_results VALUES(15,'PASSOU',jsonb_build_object('denied',SQLSTATE)); END; END $$;
RESET ROLE;
UPDATE public.user_roles SET role='coordenador' WHERE user_id='15ba9344-a725-48b8-a9f1-53de3a662af0';
SET LOCAL ROLE authenticated;
INSERT INTO access_results SELECT 8,CASE WHEN public.tem_capacidade(auth.uid(),'eventos.gerenciar') AND NOT public.tem_capacidade(auth.uid(),'financeiro.gerenciar') THEN 'PASSOU' ELSE 'FALHOU' END,'{}';
RESET ROLE;
UPDATE public.user_roles SET role='financeiro' WHERE user_id='15ba9344-a725-48b8-a9f1-53de3a662af0';
SET LOCAL ROLE authenticated;
INSERT INTO access_results SELECT 9,CASE WHEN public.tem_capacidade(auth.uid(),'financeiro.gerenciar') AND NOT public.tem_capacidade(auth.uid(),'eventos.gerenciar') AND NOT EXISTS(SELECT 1 FROM public.cobrancas WHERE empresa_id<>'bf381a72-3d4e-4ce9-920a-e4c2409bfdb8') THEN 'PASSOU' ELSE 'FALHOU' END,'{}';
RESET ROLE;
UPDATE public.user_roles SET role='supervisor' WHERE user_id='15ba9344-a725-48b8-a9f1-53de3a662af0';
SET LOCAL ROLE authenticated;
INSERT INTO access_results SELECT 10,CASE WHEN public.tem_capacidade(auth.uid(),'operacao.supervisionar') AND NOT public.tem_capacidade(auth.uid(),'financeiro.gerenciar') THEN 'PASSOU' ELSE 'FALHOU' END,'{}';
SELECT set_config('request.jwt.claim.sub','567731d0-e8d2-4584-8794-a674738e9f35',true);
DO $$ DECLARE eid uuid; BEGIN INSERT INTO access_results VALUES(16,CASE WHEN public.empresa_atual() IS NULL AND NOT public.tem_capacidade(auth.uid(),'eventos.gerenciar') THEN 'PASSOU' ELSE 'FALHOU' END,'{}'); BEGIN eid:=public.criar_empresa('Teste transacional onboarding','12345678000199'); IF eid IS NULL THEN UPDATE access_results SET status='FALHOU' WHERE scenario=16; END IF; EXCEPTION WHEN OTHERS THEN UPDATE access_results SET status='FALHOU',evidence=jsonb_build_object('error',SQLERRM) WHERE scenario=16; END; END $$;
RESET ROLE;
SELECT jsonb_agg(to_jsonb(r) ORDER BY scenario) AS tests FROM access_results r;
ROLLBACK;
